<?php
if (!defined('ABSPATH')) { exit; }
function mdg_finance_install_payload(){ return json_decode(base64_decode(''),true); }
add_action('admin_menu',function(){add_menu_page('Meta / Program Finans Kurulumu','Meta / Program Finans Kurulumu','manage_options','mdg-finance-install',function(){
if(!current_user_can('manage_options'))return;
echo '<div class="wrap"><h1>Meta / Program Finans Kurulumu</h1><p>Yalnız dört dosya. Kaynak sürümleri eşleşmeden kurulum yapılmaz. Finans kayıtları değiştirilmez.</p><table class="widefat"><tr><th>Dosya</th><th>Canlı SHA256</th><th>Durum</th></tr>';
$ready=true;$installed=true;foreach(mdg_finance_install_payload() as $f){$p=WP_CONTENT_DIR.'/'.$f['path'];$sha=is_file($p)?hash_file('sha256',$p):'missing';$ready=$ready&&($sha===$f['old']||$sha===$f['new']);$installed=$installed&&$sha===$f['new'];echo '<tr><td>'.esc_html($f['path']).'</td><td>'.esc_html($sha).'</td><td>'.esc_html($sha===$f['new']?'Yeni sürüm':($sha===$f['old']?'Hazır':'Kaynak farklı — durduruldu')).'</td></tr>';}
echo '</table><p>'.($installed?'Kurulum doğrulandı.':($ready?'Dosyalar doğrulandı; kontrollü kurulum hazır.':'Canlı kaynak farklı. Kurulum engellendi.')).'</p>';
if($ready&&!$installed){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="mdg_finance_install">';wp_nonce_field('mdg_finance_install');echo '<button class="button button-primary">Yedek Al ve Kurulumu Uygula</button></form>';}
echo '</div>';
});});
add_action('admin_post_mdg_finance_install',function(){
if(!current_user_can('manage_options'))wp_die('Yetkiniz yok.');check_admin_referer('mdg_finance_install');
$files=mdg_finance_install_payload();$backups=array();foreach($files as $f){$p=WP_CONTENT_DIR.'/'.$f['path'];$sha=is_file($p)?hash_file('sha256',$p):'missing';if($sha!==$f['old']&&$sha!==$f['new'])wp_die('Canlı kaynak değişmiş; kurulum durduruldu.');$decoded=base64_decode($f['content'],true);if(hash('sha256',$decoded)!==$f['new'])wp_die('Paket doğrulaması başarısız.');$backups[$f['path']]=is_file($p)?base64_encode(file_get_contents($p)):null;}
if(!get_option('mdg_finance_install_backup_20261008')){if(!add_option('mdg_finance_install_backup_20261008',$backups,'','no'))wp_die('Yedek alınamadı.');}
$done=array();foreach($files as $f){$p=WP_CONTENT_DIR.'/'.$f['path'];$tmp=$p.'.mdg-tmp';$bytes=base64_decode($f['content']);if(file_put_contents($tmp,$bytes,LOCK_EX)!==strlen($bytes)||!rename($tmp,$p)){foreach($done as $old){$original=$backups[$old];if(null!==$original)file_put_contents(WP_CONTENT_DIR.'/'.$old,base64_decode($original),LOCK_EX);else unlink(WP_CONTENT_DIR.'/'.$old);if(function_exists('opcache_invalidate'))opcache_invalidate(WP_CONTENT_DIR.'/'.$old,true);}wp_die('Dosya yazımı başarısız; uygulanan değişiklikler geri alındı.');}$done[]=$f['path'];if(function_exists('opcache_invalidate'))opcache_invalidate($p,true);}
wp_safe_redirect(admin_url('admin.php?page=mdg-finance-install'));exit;
});
